From 5282a93467e8e0ad4e8bd3655269c350c7daf0e3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:15:17 +0100
Subject: [PATCH] applets/webbrowser: add an option to reload the page
 periodically

Pages showing tasks, news or weather went stale until the user pressed
Reload. Add an option to reload every few minutes, which uses wall-clock
time so it catches up after sleep and waits while the page has focus.

BUG: 520138
---
 applets/webbrowser/main.xml              |  8 ++++++++
 applets/webbrowser/qml/ConfigGeneral.qml | 24 ++++++++++++++++++++++++
 applets/webbrowser/qml/main.qml          | 18 ++++++++++++++++++
 3 files changed, 50 insertions(+)

diff --git a/applets/webbrowser/main.xml b/applets/webbrowser/main.xml
index 269537109..9e6d608fe 100644
--- a/applets/webbrowser/main.xml
+++ b/applets/webbrowser/main.xml
@@ -45,5 +45,13 @@
     <entry name="privateBrowsing" type="Bool">
       <default>true</default>
     </entry>
+    <entry name="autoReload" type="Bool">
+      <default>false</default>
+    </entry>
+    <entry name="autoReloadInterval" type="Int">
+      <label>Minutes between automatic reloads of the page.</label>
+      <default>15</default>
+      <min>1</min>
+    </entry>
   </group>
 </kcfg>
diff --git a/applets/webbrowser/qml/ConfigGeneral.qml b/applets/webbrowser/qml/ConfigGeneral.qml
index a6c89dfcb..cc1e7f9a5 100644
--- a/applets/webbrowser/qml/ConfigGeneral.qml
+++ b/applets/webbrowser/qml/ConfigGeneral.qml
@@ -13,6 +13,8 @@ KCM.SimpleKCM {
     property alias cfg_useDefaultUrl: useDefaultUrlRadio.checked
     property alias cfg_defaultUrl: defaultUrl.text
     property alias cfg_privateBrowsing: privateBrowsing.checked
+    property alias cfg_autoReload: autoReload.checked
+    property alias cfg_autoReloadInterval: autoReloadInterval.value

     Kirigami.Form {
         Kirigami.FormGroup {
@@ -145,6 +147,28 @@ KCM.SimpleKCM {
                     text: i18nc("@option:radio", "Private Browsing")
                 }
             }
+            Kirigami.FormEntry {
+                contentItem: QQC2.CheckBox {
+                    id: autoReload
+                    text: i18nc("@option:check followed by a number of minutes", "Reload page every")
+                }
+                trailingItems: [
+                    QQC2.SpinBox {
+                        id: autoReloadInterval
+                        editable: true
+                        enabled: autoReload.checked
+                        from: 1
+                        to: 1440
+
+                        validator: RegularExpressionValidator {
+                            regularExpression: /\D*[0-9]{1,4}\D*/
+                        }
+
+                        textFromValue: (value, locale) => i18ncp("@item:valuesuffix", "%1 minute", "%1 minutes", value)
+                        valueFromText: (text, locale) => parseInt(text.replace(/\D/g, ""))
+                    }
+                ]
+            }
         }
     }
 }
diff --git a/applets/webbrowser/qml/main.qml b/applets/webbrowser/qml/main.qml
index a3fed26a8..d12e07b8b 100644
--- a/applets/webbrowser/qml/main.qml
+++ b/applets/webbrowser/qml/main.qml
@@ -252,8 +252,25 @@ PlasmoidItem {
                 }
             }

+            // Checks wall-clock time, so a page that went stale during sleep reloads soon after waking
+            Timer {
+                interval: 60000
+                repeat: true
+                running: Plasmoid.configuration.autoReload
+                onTriggered: {
+                    // Don't throw away what the user is typing or doing on the page
+                    if (webview.loading || (webview.activeFocus && webview.Window.active)) {
+                        return;
+                    }
+                    if (Math.round((Date.now() - webview.lastLoadTime) / interval) >= Plasmoid.configuration.autoReloadInterval) {
+                        webview.reload();
+                    }
+                }
+            }
+
             WebEngineView {
                 id: webview
+                property double lastLoadTime: Date.now()
                 anchors.fill: parent
                 settings.javascriptCanAccessClipboard: true
                 settings.javascriptCanPaste: true
@@ -324,6 +341,7 @@ PlasmoidItem {

                 onLoadingChanged: loadingInfo => {
                     if (loadingInfo.status === WebEngineLoadingInfo.LoadStartedStatus) {
+                        lastLoadTime = Date.now();
                         infoButton.dismiss();
                     } else if (loadingInfo.status === WebEngineLoadingInfo.LoadSucceededStatus) {
                         updateZoomTimer.start();
-- 
